import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor tanh_forward(torch::Tensor x);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

// ---------------------------------------------------------------------------
// Fused Tanh activation kernel written with CuTe.
//
// The (contiguous) input is viewed as a flat 1-D array and processed in
// tiles of kThreads * kItems elements. Each thread owns kItems contiguous
// elements, which CuTe `recast`s into 128-bit words so that the global
// loads/stores become fully vectorized (LDG.128 / STG.128). A predicated
// scalar path handles the final partial tile and any unaligned tensors.
// ---------------------------------------------------------------------------
template <class T, int kThreads, int kItems>
__global__ void __launch_bounds__(kThreads)
tanh_device(T const* __restrict__ X, T* __restrict__ Y, int64_t numel)
{
  using namespace cute;

  constexpr int Tile = kThreads * kItems;

  const int64_t tile_offset = (int64_t)blockIdx.x * Tile;
  if (tile_offset >= numel) return;

  const int tid = threadIdx.x;

  const bool aligned =
      ((reinterpret_cast<uintptr_t>(X) & 0xF) == 0) &&
      ((reinterpret_cast<uintptr_t>(Y) & 0xF) == 0);

  if (aligned && (tile_offset + Tile <= numel)) {
    // ---------------- Fast path: vectorized 128-bit accesses ----------------
    auto gX = make_tensor(make_gmem_ptr(X + tile_offset),
                          make_shape(Int<kThreads>{}, Int<kItems>{}),
                          make_stride(Int<kItems>{}, Int<1>{}));
    auto gY = make_tensor(make_gmem_ptr(Y + tile_offset),
                          make_shape(Int<kThreads>{}, Int<kItems>{}),
                          make_stride(Int<kItems>{}, Int<1>{}));

    // Per-thread slice: kItems contiguous elements.
    auto tgX = gX(tid, _);   // (kItems) : (1)
    auto tgY = gY(tid, _);   // (kItems) : (1)

    // Reinterpret as 128-bit vectors for wide memory transactions.
    using VecT = cute::uint128_t;
    auto tgXv = recast<VecT>(tgX);   // (kItems/4)
    auto tgYv = recast<VecT>(tgY);   // (kItems/4)

    // Register fragment holding the 128-bit vectors.
    auto rV = make_fragment_like(tgXv);
    copy(tgXv, rV);                  // vectorized global -> register

    // View the same registers as scalars and apply tanh elementwise.
    auto rF = recast<T>(rV);         // (kItems)

    // Fast-math tanh intrinsic: maps to the MUFU.TANH SFU instruction
    // (compute >= 7.5), removing the expensive polynomial/exp evaluation.
    #pragma unroll
    for (int i = 0; i < kItems; ++i) {
      rF(i) = __tanhf(rF(i));
    }

    copy(rV, tgYv);                  // vectorized register -> global
  } else {
    // ------------- Boundary / unaligned path: predicated scalar -------------
    const int64_t base = tile_offset + (int64_t)tid * kItems;
    #pragma unroll
    for (int i = 0; i < kItems; ++i) {
      const int64_t idx = base + i;
      if (idx < numel) {
        Y[idx] = __tanhf(X[idx]);
      }
    }
  }
}

// ------------------------------- Host wrapper -------------------------------
torch::Tensor tanh_forward(torch::Tensor x) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto x_c = x.contiguous();
  auto y   = torch::empty_like(x_c);

  const int64_t numel = x_c.numel();
  if (numel == 0) return y;

  constexpr int kThreads = 256;
  constexpr int kItems   = 8;
  constexpr int Tile     = kThreads * kItems;

  const int64_t blocks = (numel + Tile - 1) / Tile;
  TORCH_CHECK(blocks <= (int64_t)INT32_MAX, "tensor too large for 1-D grid");

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  tanh_device<float, kThreads, kItems><<<(unsigned)blocks, kThreads, 0, stream>>>(
      x_c.data_ptr<float>(),
      y.data_ptr<float>(),
      numel
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CuTe tanh launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

tanh_ext = load_inline(
    name="cute_tanh_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["tanh_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=['-O3', '--use_fast_math'],
    extra_include_paths=[
        # CUTLASS include root so <cute/tensor.hpp> resolves
        '/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include',
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a Tanh activation using a custom CuTe kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = tanh_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Applies Tanh activation to the input tensor.

        Args:
            x (torch.Tensor): Input tensor of any shape.

        Returns:
            torch.Tensor: Output tensor with Tanh applied, same shape as input.
        """
        return self._ext.tanh_forward(x)

