      rF(i) = __tanhf(rF(i));
    }

    copy(rV, tgYv);                  // vectorized register -> global
  } else {
    // ------------- Boundary / unaligned path: predicated scalar -------------
    const int64_t base = tile_offset + (int64_t)tid * kItems;
    #pragma unroll
    for (int i = 0; i < kItems; ++i) {
      const int64_t idx = base + i;
      if (idx < numel) {
        Y[idx] = __tanhf(X[idx]);
      }
    }
  }
}

// ------------------------------- Host wrapper -------------------------------
torch::Tensor tanh_forward(torch::Tensor x) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto x_c = x.contiguous();
  auto y   = torch::empty_like(x_c);

  const int64_t numel = x_c.numel();
  if (numel == 0) return y;

  constexpr int kThreads = 256;
  constexpr int kItems   = 8;
  constexpr int Tile     = kThreads * kItems;

  const int64_t blocks = (numel + Tile - 1) / Tile;
  TORCH_CHECK(blocks <= (int64_t)INT32_MAX, "tensor too large for 1-D grid");

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  tanh_device<float, kThreads, kItems><<<(unsigned)blocks, kThreads, 0, stream>>>(
      x_c.data_ptr<float>(),
      y.data_ptr<float>(),
      numel
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CuTe tanh launch failed: ",
              cudaGetErrorString(err));

  return y;
}
